DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.detox_action(text,uuid,integer)'::regprocedure) INTO definition; IF position('least(15,floor(n/30.0)::integer*5)' in definition)=0 THEN RAISE EXCEPTION 'detox_definition_changed'; END IF; EXECUTE replace(definition,'least(15,floor(n/30.0)::integer*5)','floor(n/30.0)::integer*5'); SELECT pg_get_functiondef('public.detox_duel_action(text,uuid)'::regprocedure) INTO definition; EXECUTE replace(definition,'IF _action=''challenge'' THEN','PERFORM pg_advisory_xact_lock(hashtextextended(greatest(uid::text,_target::text),17)); IF _action=''challenge'' THEN'); END $$;